cat > main.ts <<'EOF'
const path = Deno.args[0];
if (path === undefined) {
  console.error("usage: main.ts <file>");
  Deno.exit(2);
}

const bytes = Deno.readFileSync(path);
const counts = new Map<string, number>();
let word = "";

const flush = () => {
  if (word !== "") {
    counts.set(word, (counts.get(word) ?? 0) + 1);
    word = "";
  }
};

for (const b of bytes) {
  if (b >= 0x41 && b <= 0x5a) word += String.fromCharCode(b + 32);
  else if ((b >= 0x61 && b <= 0x7a) || (b >= 0x30 && b <= 0x39)) {
    word += String.fromCharCode(b);
  } else flush();
}
flush();

const top = [...counts].sort((a, b) =>
  b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)
).slice(0, 10);

const out = top.map(([w, c]) => `${w} ${c}\n`).join("");
Deno.stdout.writeSync(new TextEncoder().encode(out));
EOF
